// A frozen lookup table is the entire contract between the AI service and the UI.
// Adding a capability = adding a row. The socket layer never changes.
export const TOOL_MAP = Object.freeze({
  "display-core-context": MarketingInsights,
  "show-hypothesis": MultiSelectHypothesis,
  "show-variant-generation-button": GenerateVariantCardInChat,
  "show-all-providers": AdProviders,
  "list-ads": AdList,

  // segment creation and analysis tools
  "show-generated-segments": GeneratedSegmentsDisplay,
  "show-table": ShowTable,
  "show-ranking-table": ShowRankingTable,
  "segment-attachment-success": SegmentAttachmentSuccess,

  // winning variant tools
  "show-winning-variants": WinningVariantsTable,
  "show-variant-summary": ShowVariantSummary,
} as const);
